fn append_vignette_vertices(vertices: &mut Vec<UiVertex>) {
    // Approximate the old smooth radial post-process with a few interpolated
    // rings. The centre is an actual hole, so the rasterizer does no vignette
    // work there. 32 segments keeps the zero-alpha boundary visually round.
    const SEGMENTS: usize = 32;
    const RADII_NDC: [f32; 5] = [0.56, 0.80, 1.04, 1.28, 1.56];

    let alpha_at_radius = |radius_ndc: f32| {
        let radius_uv = radius_ndc * 0.5;
        let t = ((radius_uv - 0.28) / (0.78 - 0.28)).clamp(0.0, 1.0);
        let edge = t * t * (3.0 - 2.0 * t);
        edge * 0.28
    };
    let make_vertex = |radius: f32, angle: f32| UiVertex {
        position: [angle.cos() * radius, angle.sin() * radius],
        uv: [0.0, 0.0],
        color: [0.0, 0.0, 0.0, alpha_at_radius(radius)],
        textured: 0.0,
    };

    for ring in RADII_NDC.windows(2) {
        let inner = ring[0];
        let outer = ring[1];
        for segment in 0..SEGMENTS {
            let a0 = std::f32::consts::TAU * segment as f32 / SEGMENTS as f32;
            let a1 = std::f32::consts::TAU * (segment + 1) as f32 / SEGMENTS as f32;
            let i0 = make_vertex(inner, a0);
            let i1 = make_vertex(inner, a1);
            let o0 = make_vertex(outer, a0);
            let o1 = make_vertex(outer, a1);
            vertices.extend_from_slice(&[i0, o0, o1, i0, o1, i1]);
        }
    }
}

fn env_flag(name: &str) -> bool {
    std::env::var(name).ok().is_some_and(|value| {
        matches!(
            value.trim().to_ascii_lowercase().as_str(),
            "1" | "true" | "yes" | "on"
        )
    })
}

#[derive(Clone, Copy, Debug)]
pub struct InputLatencySample {
    pub sequence: u64,
    pub event_at: Instant,
    pub simulation_at: Instant,
}

#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub enum ViewLatchMode {
    #[default]
    Disabled,
    /// First-person view: the newest input orientation is the final camera rotation.
    Direct,
    /// Ordinary local third person. Target damping/collision were resolved by
    /// CGame; the renderer may rebuild only the angle-dependent OpenJK orbit math.
    ThirdPerson(ThirdPersonLateLatchView),
}

/// Tiny single-writer/multi-reader mailbox for subframe *input* view rotation.
/// The main thread writes the latest local-player yaw/pitch and mouse timestamp
/// without taking the RenderSnapshot mutex. The renderer decides how that input
/// maps onto the final first- or third-person camera via `ViewLatchMode`.
struct LatestViewState {
    epoch: Instant,
    version: AtomicU64,
    yaw_bits: AtomicU32,
    pitch_bits: AtomicU32,
    input_sequence: AtomicU64,
    event_ns: AtomicU64,
    simulation_ns: AtomicU64,
}

#[derive(Clone, Copy)]
struct LatestViewSample {
    yaw: f32,
    pitch: f32,
    input: Option<InputLatencySample>,
}

#[derive(Clone, Copy)]
struct ViewSampleMeasurement {
    input: InputLatencySample,
    sampled_at: Instant,
}

impl LatestViewState {
    fn new(camera: Camera) -> Self {
        Self {
            epoch: Instant::now(),
            version: AtomicU64::new(0),
            yaw_bits: AtomicU32::new(camera.yaw.to_bits()),
            pitch_bits: AtomicU32::new(camera.pitch.to_bits()),
            input_sequence: AtomicU64::new(0),
            event_ns: AtomicU64::new(0),
            simulation_ns: AtomicU64::new(0),
        }
    }

    #[inline]
    fn instant_ns(&self, instant: Instant) -> Option<u64> {
        instant.checked_duration_since(self.epoch).map(|elapsed| {
            elapsed.as_nanos().min(u128::from(u64::MAX)) as u64
        })
    }

    fn publish_rotation(&self, yaw: f32, pitch: f32, input: Option<InputLatencySample>) {
        // Single writer (winit/main thread): odd marks an in-progress update;
        // even + Release publishes the complete tuple to the render thread.
        // AcqRel on the opening RMW keeps the payload stores after the odd
        // marker; Release on the closing RMW publishes the complete tuple.
        // That gives the Acquire/Acquire reader a real seqlock boundary rather
        // than relying on relaxed operations not being reordered.
        self.version.fetch_add(1, Ordering::AcqRel);
        self.yaw_bits.store(yaw.to_bits(), Ordering::Relaxed);
        self.pitch_bits.store(pitch.to_bits(), Ordering::Relaxed);
        if let Some(sample) = input {
            if let (Some(event_ns), Some(simulation_ns)) = (
                self.instant_ns(sample.event_at),
                self.instant_ns(sample.simulation_at),
            ) {
                self.input_sequence.store(sample.sequence, Ordering::Relaxed);
                self.event_ns.store(event_ns, Ordering::Relaxed);
                self.simulation_ns.store(simulation_ns, Ordering::Relaxed);
            }
        }
        self.version.fetch_add(1, Ordering::Release);
    }

    fn load(&self) -> LatestViewSample {
        loop {
            let before = self.version.load(Ordering::Acquire);
            if before & 1 != 0 {
                std::hint::spin_loop();
                continue;
            }
            let yaw = f32::from_bits(self.yaw_bits.load(Ordering::Relaxed));
            let pitch = f32::from_bits(self.pitch_bits.load(Ordering::Relaxed));
            let sequence = self.input_sequence.load(Ordering::Relaxed);
            let event_ns = self.event_ns.load(Ordering::Relaxed);
            let simulation_ns = self.simulation_ns.load(Ordering::Relaxed);
            let after = self.version.load(Ordering::Acquire);
            if before != after {
                std::hint::spin_loop();
                continue;
            }
            let input = (sequence != 0).then(|| InputLatencySample {
                sequence,
                event_at: self.epoch + Duration::from_nanos(event_ns),
                simulation_at: self.epoch + Duration::from_nanos(simulation_ns),
            });
            return LatestViewSample { yaw, pitch, input };
        }
    }
}

#[inline]
fn sample_view_rotation(
    camera: &mut Camera,
    state: &LatestViewState,
    mode: ViewLatchMode,
) -> Option<ViewSampleMeasurement> {
    if mode == ViewLatchMode::Disabled {
        return None;
    }
    let sample = state.load();
    match mode {
        ViewLatchMode::Disabled => unreachable!(),
        ViewLatchMode::Direct => {
            camera.yaw = sample.yaw;
            camera.pitch = sample.pitch;
            // The base position (already shaken by the frame setup) is untouched.
            camera.apply_shake_angles();
        }
        ViewLatchMode::ThirdPerson(latch) => {
            // LatestViewState uses renderer conventions (yaw radians, positive
            // pitch up). The OpenJK camera port consumes native JKA degrees,
            // where positive pitch points down. This is the newest real input,
            // never an extrapolated/predicted angle.
            let view = late_latch_third_person_view(
                latch,
                [-sample.pitch.to_degrees(), sample.yaw.to_degrees(), 0.0],
            );
            camera.position = Vec3::from_array(scene::render_position(view.origin));
            camera.yaw = view.angles[1].to_radians();
            camera.pitch = -view.angles[0].to_radians();
            camera.apply_shake();
        }
    }
    let sampled_at = Instant::now();
    sample
        .input
        .map(|input| ViewSampleMeasurement { input, sampled_at })
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum DynamicModelAlphaMode {
    Opaque,
    Mask,
    Blend,
    /// Alpha-tested material plus OpenJK RF_FORCE_ENT_ALPHA semantics.
    MaskBlend,
    /// Unlit GL_ONE GL_ONE additive stage. Alpha does not scale source RGB.
    AdditiveOne,
    /// Unlit GL_SRC_ALPHA GL_ONE additive presentation primitive.
    Additive,
    /// Unlit GL_SRC_ALPHA GL_ONE_MINUS_SRC_ALPHA (FX smoke, sprites).
    BlendUnlit,
    /// GL_DST_COLOR GL_ZERO: multiplies what is already drawn (FX filters).
    Modulate,
    /// GL_DST_COLOR GL_SRC_COLOR: JKA 2x modulation (2 * source * destination).
    Modulate2x,
    /// GL_ZERO GL_ONE_MINUS_SRC_COLOR.
    Darken,
}

impl DynamicModelAlphaMode {
    const COUNT: usize = 10;

    /// Dense index for per-alpha-mode pipeline tables and draw bitmasks.
    const fn index(self) -> usize {
        match self {
            Self::Opaque => 0,
            Self::Mask => 1,
            Self::Blend => 2,
            Self::MaskBlend => 3,
            Self::AdditiveOne => 4,
            Self::Additive => 5,
            Self::BlendUnlit => 6,
            Self::Modulate => 7,
            Self::Modulate2x => 8,
            Self::Darken => 9,
        }
    }
}

const DYNAMIC_MODEL_ALPHA_ORDER: [DynamicModelAlphaMode; 10] = [
    DynamicModelAlphaMode::Opaque,
    DynamicModelAlphaMode::Mask,
    DynamicModelAlphaMode::MaskBlend,
    DynamicModelAlphaMode::Modulate,
    DynamicModelAlphaMode::Modulate2x,
    DynamicModelAlphaMode::Darken,
    DynamicModelAlphaMode::Blend,
    DynamicModelAlphaMode::BlendUnlit,
    DynamicModelAlphaMode::AdditiveOne,
    DynamicModelAlphaMode::Additive,
];

/// Dynamic surfaces come from two geometry backends: transient CPU meshes
/// (including FX such as saber blades) and GPU-skinned Ghoul2 meshes. The
/// depth-writing phase must finish across *both* backends before any blended
/// surface is submitted. Otherwise a CPU additive effect drawn first can be
/// overwritten later by an opaque GPU-skinned player even when the effect is
/// physically in front of the player.
#[inline]
fn dynamic_model_writes_depth(alpha_mode: DynamicModelAlphaMode) -> bool {
    matches!(alpha_mode, DynamicModelAlphaMode::Opaque | DynamicModelAlphaMode::Mask)
}

#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
pub struct DynamicModelVertex {
    pub position: [f32; 3],
    pub normal: [f32; 3],
    pub uv: [f32; 2],
    /// OpenJK refEntity shaderRGBA equivalent. Player presentation currently
    /// uses white RGB and the CG_CheckThirdPersonAlpha alpha channel.
    pub color: [f32; 4],
}

/// Bind-pose GLM vertex used by the optional GPU Ghoul2 skinning path. Bone
/// indices are GLA/global indices, resolved from the GLM surface-local table at
/// model registration time so the shader does no hierarchy indirection.
#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
pub struct Ghoul2GpuVertex {
    pub position: [f32; 3],
    pub normal: [f32; 3],
    pub uv: [f32; 2],
    pub bone_indices: [u32; 4],
    pub weights: [f32; 4],
    pub weight_count: u32,
    pub _padding: [u32; 3],
}

/// Storage-buffer-safe repack used only by the RT-on compute skinning path.
/// Keeping vec4-sized fields avoids WGSL storage-layout padding ambiguity while
/// the normal RT-off raster path keeps its original compact vertex unchanged.
#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
struct Ghoul2RtInputVertex {
    position_uv_x: [f32; 4],
    normal_uv_y: [f32; 4],
    bone_indices: [u32; 4],
    weights: [f32; 4],
    params: [u32; 4],
}

impl From<&Ghoul2GpuVertex> for Ghoul2RtInputVertex {
    fn from(vertex: &Ghoul2GpuVertex) -> Self {
        Self {
            position_uv_x: [vertex.position[0], vertex.position[1], vertex.position[2], vertex.uv[0]],
            normal_uv_y: [vertex.normal[0], vertex.normal[1], vertex.normal[2], vertex.uv[1]],
            bone_indices: vertex.bone_indices,
            weights: vertex.weights,
            params: [vertex.weight_count, 0, 0, 0],
        }
    }
}

/// One final CPU-evaluated Ghoul2 bone matrix. GPU mode intentionally keeps
/// animation, BG_G2PlayerAngles and bolt semantics on the CPU; only the GLM
/// vertex deformation moves to the vertex shader.
#[repr(C)]
#[derive(Clone, Copy, Debug, Pod, Zeroable)]
pub struct Ghoul2GpuBone {
    pub row0: [f32; 4],
    pub row1: [f32; 4],
    pub row2: [f32; 4],
}

#[derive(Clone, Debug)]
pub struct Ghoul2GpuSkinning {
    /// Stable geometry cache key, e.g. `models/players/kyle/model.glm#lod0#surface3`.
    pub mesh_key: Arc<str>,
    pub vertices: Arc<Vec<Ghoul2GpuVertex>>,
    pub indices: Arc<Vec<u32>>,
    /// Shared across all surfaces belonging to one evaluated pose.
    pub bones: Arc<Vec<Ghoul2GpuBone>>,
    /// JKA entity/model axis and origin. The shader converts the result to the
    /// renderer's [x,z,-y] coordinate convention after skinning.
    pub axis: [[f32; 3]; 3],
    pub origin: [f32; 3],
    pub color: [f32; 4],
    /// Texture-coordinate transform `uv * xy + zw`; [1, 1, 0, 0] is identity.
    pub uv_xform: [f32; 4],
    /// `alphaGen lightingSpecular`: JKA world-space (light, viewer) points. The
    /// shader multiplies the draw alpha by q3's `(R.V)^4` specular term.
    pub specular: Option<([f32; 3], [f32; 3])>,
    /// `deformVertexes bulge <0> <height> <0>` (JKA's static-offset special
    /// case; see `jka_assets::shader::Bulge::is_static`): a constant JKA-unit
    /// offset along the model-space vertex normal, applied before the entity
    /// transform. Zero for ordinary surfaces. Packed into the GPU draw's
    /// otherwise-unused `spec_viewer.w` (mutually exclusive with specular).
    pub bulge_height: f32,
    /// `tcGen environment` (e.g. `gfx/misc/personalshield`'s chrome stage):
    /// replaces `uv_xform`'s mapping of the base mesh UVs with q3's reflection-
    /// vector environment mapping (`RB_CalcEnvironmentTexCoords`).
    pub env_map: bool,
}

