fn gpu_point_lights(
    lights: &[scene::DynamicLight],
    shadow_slot_by_light: &[u32],
) -> Vec<GpuPointLight> {
    let mut gpu_lights = lights
        .iter()
        .enumerate()
        .map(|(index, light)| GpuPointLight {
            position_radius: [
                light.position[0],
                light.position[1],
                light.position[2],
                light.radius,
            ],
            color_intensity: [
                light.color[0],
                light.color[1],
                light.color[2],
                light.intensity,
            ],
            emitter: [
                light.emitter_normal[0],
                light.emitter_normal[1],
                light.emitter_normal[2],
                if light.emitter_normal.iter().any(|value| value.abs() > 1e-6) {
                    if light.emitter_two_sided {
                        2.0
                    } else {
                        1.0
                    }
                } else if light.falloff.shader_value() > 0.5 {
                    if !light.angle_attenuation {
                        -1.0
                    } else if light.angle_scale != 0.0 {
                        -(2.0 + light.angle_scale.abs())
                    } else {
                        -2.0
                    }
                } else {
                    0.0
                },
            ],
            shadow: [
                shadow_slot_by_light.get(index).copied().unwrap_or(0) as f32,
                light.falloff.shader_value(),
                light.extra_distance,
                0.0,
            ],
        })
        .collect::<Vec<_>>();
    if gpu_lights.is_empty() {
        gpu_lights.push(GpuPointLight::zeroed());
    }
    gpu_lights
}

fn local_light_is_pvs_relevant(world: &WorldGpu, light: scene::DynamicLight) -> bool {
    let Some(cluster) = world.last_cluster.flatten() else {
        return true;
    };

    if let Some(indices) = world.full_visible_batches_by_cluster.get(cluster) {
        if !indices.is_empty() {
            return indices.iter().any(|&batch_index| {
                let batch = &world.full_batches[batch_index];
                aabb_intersects_sphere(
                    batch.bounds_min,
                    batch.bounds_max,
                    light.position,
                    light.radius,
                )
            });
        }
    }

    world
        .coarse_visible_batches_by_cluster
        .get(cluster)
        .is_none_or(|indices| {
            indices.iter().any(|&batch_index| {
                let batch = &world.coarse_batches[batch_index];
                aabb_intersects_sphere(
                    batch.bounds_min,
                    batch.bounds_max,
                    light.position,
                    light.radius,
                )
            })
        })
}

fn local_shadow_importance(
    light: scene::DynamicLight,
    camera_position: Vec3,
    already_active: bool,
) -> f32 {
    if !light.intensity.is_finite()
        || !light.radius.is_finite()
        || light.intensity <= 0.0
        || light.radius <= LOCAL_SHADOW_NEAR * 2.0
    {
        return 0.0;
    }

    let distance = Vec3::from_array(light.position)
        .distance(camera_position)
        .max(LOCAL_SHADOW_NEAR);
    let radius = light.radius.max(LOCAL_SHADOW_NEAR);
    let outside_distance = (distance - radius).max(0.0);
    let projected_influence = (radius / distance.max(radius * 0.25)).clamp(0.0, 4.0);
    let proximity = 1.0 / (1.0 + outside_distance / radius);
    let energy = light.intensity.max(0.0).sqrt();
    let emitter_normal = Vec3::from_array(light.emitter_normal);
    let emitter_relevance = if emitter_normal.length_squared() > 1e-6 {
        let to_camera = (camera_position - Vec3::from_array(light.position)).normalize_or_zero();
        let facing = emitter_normal.normalize().dot(to_camera);
        if light.emitter_two_sided {
            facing.abs()
        } else {
            facing.max(0.0)
        }
    } else {
        1.0
    };
    let hysteresis = if already_active {
        LOCAL_SHADOW_HYSTERESIS
    } else {
        1.0
    };
    energy * projected_influence * projected_influence * proximity * emitter_relevance * hysteresis
}

fn select_relevant_shadow_lights(
    world: &WorldGpu,
    camera: &Camera,
    include_point_lights: bool,
    include_area_lights: bool,
) -> Vec<usize> {
    let mut candidates = world
        .dynamic_lights
        .iter()
        .copied()
        .enumerate()
        .filter_map(|(index, light)| {
            if !light.surface_lighting {
                return None;
            }
            let is_area = light.emitter_normal.iter().any(|value| value.abs() > 1e-6);
            if is_area && !include_area_lights {
                return None;
            }
            if !is_area && !include_point_lights {
                return None;
            }
            // A single cubemap sample cannot correctly shadow both hemispheres
            // of a two-sided area emitter. One-sided q3map emitters are offset
            // from their source plane and can use the normal local-shadow cache.
            if light.emitter_two_sided
                && light.emitter_normal.iter().any(|value| value.abs() > 1e-6)
            {
                return None;
            }
            if !local_light_is_pvs_relevant(world, light) {
                return None;
            }
            let score = local_shadow_importance(
                light,
                camera.position,
                world.local_shadows.active_light_indices.contains(&index),
            );
            (score > 0.0).then_some((index, score))
        })
        .collect::<Vec<_>>();
    candidates.sort_by(|(a_index, a_score), (b_index, b_score)| {
        b_score
            .total_cmp(a_score)
            .then_with(|| a_index.cmp(b_index))
    });
    candidates.truncate(MAX_LOCAL_SHADOW_LIGHTS);
    candidates.into_iter().map(|(index, _)| index).collect()
}

fn local_shadow_face_matrices(position: Vec3, radius: f32) -> [Mat4; 6] {
    let far_plane = radius.max(LOCAL_SHADOW_NEAR + 1.0);
    let projection = Mat4::perspective_rh(
        std::f32::consts::FRAC_PI_2,
        1.0,
        LOCAL_SHADOW_NEAR,
        far_plane,
    );
    let faces = [
        (Vec3::X, -Vec3::Y),
        (-Vec3::X, -Vec3::Y),
        (Vec3::Y, Vec3::Z),
        (-Vec3::Y, -Vec3::Z),
        (Vec3::Z, -Vec3::Y),
        (-Vec3::Z, -Vec3::Y),
    ];
    faces.map(|(direction, up)| projection * Mat4::look_to_rh(position, direction, up))
}

fn create_local_shadow_resources(
    device: &wgpu::Device,
    caster_layout: &wgpu::BindGroupLayout,
) -> LocalShadowResources {
    let layer_count = u32::try_from(LOCAL_SHADOW_CACHE_SLOTS * 6).unwrap_or(6);
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("JKA local-light shadow cubemap cache"),
        size: wgpu::Extent3d {
            width: LOCAL_SHADOW_MAP_SIZE,
            height: LOCAL_SHADOW_MAP_SIZE,
            depth_or_array_layers: layer_count,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: DEPTH_FORMAT,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::TEXTURE_BINDING,
        view_formats: &[],
    });
    let cube_view = texture.create_view(&wgpu::TextureViewDescriptor {
        label: Some("JKA local-light shadow cache cube-array view"),
        format: Some(DEPTH_FORMAT),
        dimension: Some(wgpu::TextureViewDimension::CubeArray),
        base_mip_level: 0,
        mip_level_count: Some(1),
        base_array_layer: 0,
        array_layer_count: Some(layer_count),
        aspect: wgpu::TextureAspect::DepthOnly,
        usage: Some(wgpu::TextureUsages::TEXTURE_BINDING),
    });
    let sampler = device.create_sampler(&wgpu::SamplerDescriptor {
        label: Some("JKA local-light shadow comparison sampler"),
        address_mode_u: wgpu::AddressMode::ClampToEdge,
        address_mode_v: wgpu::AddressMode::ClampToEdge,
        address_mode_w: wgpu::AddressMode::ClampToEdge,
        mag_filter: wgpu::FilterMode::Nearest,
        min_filter: wgpu::FilterMode::Nearest,
        compare: Some(wgpu::CompareFunction::LessEqual),
        ..Default::default()
    });

    let identity = ShadowCasterUniform {
        view_proj: Mat4::IDENTITY.to_cols_array_2d(),
        camera_pos_time: [0.0; 4],
    };
    let mut layer_views = Vec::with_capacity(LOCAL_SHADOW_CACHE_SLOTS * 6);
    let mut caster_buffers = Vec::with_capacity(LOCAL_SHADOW_CACHE_SLOTS * 6);
    let mut caster_bind_groups = Vec::with_capacity(LOCAL_SHADOW_CACHE_SLOTS * 6);
    for layer in 0..LOCAL_SHADOW_CACHE_SLOTS * 6 {
        layer_views.push(texture.create_view(&wgpu::TextureViewDescriptor {
            label: Some("JKA local-light cached shadow face"),
            format: Some(DEPTH_FORMAT),
            dimension: Some(wgpu::TextureViewDimension::D2),
            base_mip_level: 0,
            mip_level_count: Some(1),
            base_array_layer: u32::try_from(layer).unwrap_or(0),
            array_layer_count: Some(1),
            aspect: wgpu::TextureAspect::DepthOnly,
            usage: Some(wgpu::TextureUsages::RENDER_ATTACHMENT),
        }));
        let buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("JKA local-light cached shadow caster uniform"),
            contents: bytemuck::bytes_of(&identity),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        caster_bind_groups.push(device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("JKA local-light cached shadow caster bind group"),
            layout: caster_layout,
            entries: &[wgpu::BindGroupEntry {
                binding: 0,
                resource: buffer.as_entire_binding(),
            }],
        }));
        caster_buffers.push(buffer);
    }

    LocalShadowResources {
        _texture: texture,
        cube_view,
        sampler,
        layer_views,
        caster_buffers,
        caster_bind_groups,
        cache_entries: vec![LocalShadowCacheEntry::default(); LOCAL_SHADOW_CACHE_SLOTS],
        active_light_indices: Vec::new(),
        pending_slots: Vec::new(),
        shadowed_light_count: 0,
        selection_cluster: None,
        selection_position: None,
        selection_serial: 0,
    }
}

fn aabb_intersects_sphere(
    minimum: [f32; 3],
    maximum: [f32; 3],
    center: [f32; 3],
    radius: f32,
) -> bool {
    let mut squared_distance = 0.0_f32;
    for axis in 0..3 {
        let value = center[axis];
        let nearest = value.clamp(minimum[axis], maximum[axis]);
        let delta = value - nearest;
        squared_distance += delta * delta;
    }
    squared_distance <= radius * radius
}

/// True when every point of the box is more than one unit on the negative
/// side of `plane` (n·p + d < 0), i.e. fully discarded by a clip plane.
fn aabb_behind_plane(minimum: [f32; 3], maximum: [f32; 3], plane: [f32; 4]) -> bool {
    // The box corner furthest along the plane normal.
    let farthest: f32 = (0..3)
        .map(|axis| plane[axis] * if plane[axis] >= 0.0 { maximum[axis] } else { minimum[axis] })
        .sum();
    farthest + plane[3] < -1.0
}

fn aabb_intersects_clip_frustum(minimum: [f32; 3], maximum: [f32; 3], view_proj: Mat4) -> bool {
    let corners = [
        Vec3::new(minimum[0], minimum[1], minimum[2]),
        Vec3::new(maximum[0], minimum[1], minimum[2]),
        Vec3::new(minimum[0], maximum[1], minimum[2]),
        Vec3::new(maximum[0], maximum[1], minimum[2]),
        Vec3::new(minimum[0], minimum[1], maximum[2]),
        Vec3::new(maximum[0], minimum[1], maximum[2]),
        Vec3::new(minimum[0], maximum[1], maximum[2]),
        Vec3::new(maximum[0], maximum[1], maximum[2]),
    ];
    let clip = corners.map(|corner| view_proj * corner.extend(1.0));

    let outside_left = clip.iter().all(|point| point.x < -point.w);
    let outside_right = clip.iter().all(|point| point.x > point.w);
    let outside_bottom = clip.iter().all(|point| point.y < -point.w);
    let outside_top = clip.iter().all(|point| point.y > point.w);
    // glam's *_rh projection helpers use wgpu/D3D depth convention: z in [0, w].
    let outside_near = clip.iter().all(|point| point.z < 0.0);
    let outside_far = clip.iter().all(|point| point.z > point.w);

    !(outside_left || outside_right || outside_bottom || outside_top || outside_near || outside_far)
}

/// Culls a caster against a directional cascade. Only the sides of the box are
/// tested against the sun-facing depth range: anything between the sun and the
/// cascade can still shadow it (the caster pipelines run with unclipped depth),
/// so rejecting on the sunward plane deleted roofs whenever the view frustum's
/// light-space extent happened to end below them. Only the plane beyond the
/// cascade, away from the sun, may cull. `reverse_z` selects which clip-z end
/// that is (Bevy cascades are reverse-Z, the legacy ones are not).
fn aabb_intersects_shadow_frustum(
    minimum: [f32; 3],
    maximum: [f32; 3],
    view_proj: Mat4,
    reverse_z: bool,
) -> bool {
    let corners = [
        Vec3::new(minimum[0], minimum[1], minimum[2]),
        Vec3::new(maximum[0], minimum[1], minimum[2]),
        Vec3::new(minimum[0], maximum[1], minimum[2]),
        Vec3::new(maximum[0], maximum[1], minimum[2]),
        Vec3::new(minimum[0], minimum[1], maximum[2]),
        Vec3::new(maximum[0], minimum[1], maximum[2]),
        Vec3::new(minimum[0], maximum[1], maximum[2]),
        Vec3::new(maximum[0], maximum[1], maximum[2]),
    ];
    let clip = corners.map(|corner| view_proj * corner.extend(1.0));

    let outside_left = clip.iter().all(|point| point.x < -point.w);
    let outside_right = clip.iter().all(|point| point.x > point.w);
    let outside_bottom = clip.iter().all(|point| point.y < -point.w);
    let outside_top = clip.iter().all(|point| point.y > point.w);
    let beyond_cascade = if reverse_z {
        clip.iter().all(|point| point.z < 0.0)
    } else {
        clip.iter().all(|point| point.z > point.w)
    };

    !(outside_left || outside_right || outside_bottom || outside_top || beyond_cascade)
}

/// Produce the hardware-ray-query BSP shader from the authoritative raster BSP
/// shader. Keeping this as a narrow source transform means the RT variant shares
/// every JKA lighting/material rule with the normal shader; sun and local-light
/// visibility are replaced. The stock WGSL is still what all raster modes
/// compile.
/// Wrap the full light evaluation so attenuation, BRDF and visibility use the
/// same sample. In particular, `continue` must reject only the current sample.
fn rt_sampled_light_loops(source: &str) -> Result<String, String> {
    const LOOP: &str = "for (var i = 0u; i < min(cluster.count, 32u); i += 1u) {";
    const LIGHT: &str = "let light = dynamic_lights[cluster.indices[i]];";
    let mut result = source.to_owned();
    let starts = source.match_indices(LOOP).map(|(start, _)| start).collect::<Vec<_>>();
    if starts.is_empty() { return Err("RT light loops not found".into()); }
    for start in starts.into_iter().rev() {
        let body = start + LOOP.len();
        let mut depth = 1;
        let end = source[body..].char_indices().find_map(|(offset, c)| {
            if c == '{' { depth += 1; }
            if c == '}' { depth -= 1; }
            (depth == 0).then_some(body + offset)
        }).ok_or("unterminated RT light loop")?;
        let original = &source[body..end];
        if original.matches(LIGHT).count() != 1 { return Err("RT light lookup anchor changed".into()); }
        // Local lights are always traced directly (never cached): they are
        // already gated by real cluster membership, so most receivers pay
        // nothing for lights that aren't nearby. Only the per-sample area-light
        // loop (independent of caching) is introduced here.
        let sampled = original.replace(LIGHT,
            "let light = rt_sample_local_emitter(rt_source, input, cluster.indices[i], rt_sample_index, rt_count);");
        result.replace_range(start..end, &format!("{LOOP}\n        let rt_source = dynamic_lights[cluster.indices[i]];\n        let rt_count = rt_local_sample_count(rt_source);\n        for (var rt_sample_index = 0u; rt_sample_index < rt_count; rt_sample_index += 1u) {{{sampled}\n        }}\n    "));
    }
    Ok(result)
}

/// A complete world shader: a variant's base source plus the modules every world
/// variant shares (the weather maths and forward weather shading, and surface
/// deformation).
fn compose_world_shader(base: &str) -> String {
    format!(
        "{}\n{}",
        weather::with_world_weather(base),
        include_str!("surface_deformation.wgsl")
    )
}

fn ray_traced_world_shader_source(base: &str) -> Result<String, String> {
    const BINDING: &str = "@group(3) @binding(7) var sky_admission_texture: texture_depth_2d_array;";
    const CASCADE_FN: &str = "fn cascaded_shadow_visibility(input: VertexOut, normal: vec3<f32>) -> f32 {";
    const LOCAL_FN: &str = "fn local_light_shadow_visibility(light: PointLight, world_position: vec3<f32>, receiver_normal: vec3<f32>) -> f32 {";
    const SURFACE_SUN: &str = "        let shadow_visibility = cascaded_shadow_visibility(input, input.world_normal);\n        let light_direction = normalize(shadow_settings.light_direction_enabled.xyz);\n        let sun_facing = max(dot(normalize(input.world_normal), -light_direction), 0.0);";

    if !base.contains(BINDING) {
        return Err("group-3 sky-admission binding anchor not found".to_string());
    }
    if !base.contains(CASCADE_FN) {
        return Err("cascaded_shadow_visibility anchor not found".to_string());
    }
    if !base.contains(LOCAL_FN) {
        return Err("local_light_shadow_visibility anchor not found".to_string());
    }
    // Both checked-in shaders can have CRLF on Windows. Normalize only the
    // generated RT variant so multiline source anchors are platform-independent.
    let base = base.replace("\r\n", "\n");
    if !base.contains(SURFACE_SUN) {
        return Err("surface sun contribution anchor not found".to_string());
    }

    let mut source = format!("enable wgpu_ray_query;\n{base}");
    source = source.replacen(
        "override ENABLE_CASCADED_SHADOWS: bool = false;",
        "override ENABLE_CASCADED_SHADOWS: bool = false;\noverride ENABLE_RAY_TRACED_SHADOWS: bool = false;\noverride ENABLE_RAY_TRACED_SUN: bool = false;",
        1,
    );
    source = source.replacen(
        BINDING,
        concat!(
            "@group(3) @binding(7) var sky_admission_texture: texture_depth_2d_array;\n",
            "@group(3) @binding(8) var rt_shadow_scene: acceleration_structure;\n",
            "\nstruct RtAlphaVertex {\n    position_u: vec4<f32>,\n    normal_v: vec4<f32>,\n    lightmap_alpha: vec4<f32>,\n};\n\nstruct RtAlphaGeometry {\n    values: vec4<u32>,\n};\n\nstruct RtAlphaMaterial {\n    header: vec4<u32>,\n    vector_s: vec4<f32>,\n    vector_t: vec4<f32>,\n    mods: array<vec4<f32>, 8>,\n    color: vec4<f32>,\n    params: vec4<f32>,\n    texture: vec4<u32>,\n};\n\nstruct RtAlphaTexture {\n    values: vec4<u32>,\n};\n\n@group(3) @binding(9) var<storage, read> rt_alpha_vertices: array<RtAlphaVertex>;\n@group(3) @binding(10) var<storage, read> rt_alpha_indices: array<u32>;\n@group(3) @binding(11) var<storage, read> rt_alpha_geometries: array<RtAlphaGeometry>;\n@group(3) @binding(12) var<storage, read> rt_alpha_materials: array<RtAlphaMaterial>;\n@group(3) @binding(13) var<storage, read> rt_alpha_textures: array<RtAlphaTexture>;\n@group(3) @binding(14) var<storage, read> rt_alpha_texels: array<u32>;"
        ),
        1,
    );

    // The shared ray-query core (sampling, alpha-tested candidate handling,
    // shadow-ray helpers). Lives in its own file so the world shader, the sun
    // compute pass and the model receivers all read one reviewable source.
    let rt_visibility = include_str!("rt_core.wgsl").replace("\r\n", "\n");
    source = source.replacen(
        CASCADE_FN,
        &format!(
            "{rt_visibility}{CASCADE_FN}\n    if (ENABLE_RAY_TRACED_SUN) {{\n        return ray_traced_shadow_visibility(input, normal);\n    }}"
        ),
        1,
    );

    source = source.replacen(
        LOCAL_FN,
        &format!(
            "{LOCAL_FN}\n    if (ENABLE_RAY_TRACED_SHADOWS) {{\n        return ray_traced_local_shadow_visibility(light, world_position, receiver_normal);\n    }}"
        ),
        1,
    );

    // The lean shader compiles the sun-shadow darkening out unless a cascade is
    // enabled. The RT sun is not a cascade, so open that gate for it. Absent in
    // bsp.wgsl, which keeps the block unconditional; the no-op replace is fine.
    source = source.replacen(
        "    if (ENABLE_CASCADED_SHADOWS && (material.header.z & 4u) != 0u) {\n        let shadow_visibility = cascaded_shadow_visibility(",
        "    if ((ENABLE_CASCADED_SHADOWS || ENABLE_RAY_TRACED_SUN) && (material.header.z & 4u) != 0u) {\n        let shadow_visibility = cascaded_shadow_visibility(",
        1,
    );

    // Ordinary BSP sun visibility is multiplied by sun_facing and strength.
    // Avoid a full traversal when that multiplier is zero. Keep this at the
    // contribution site: ocean specular uses the shared visibility helper too,
    // and must retain its own receiver rules.
    source = source.replacen(
        SURFACE_SUN,
        "        let light_direction = normalize(shadow_settings.light_direction_enabled.xyz);\n        let sun_facing = max(dot(normalize(input.world_normal), -light_direction), 0.0);\n        var shadow_visibility = 1.0;\n        if (sun_facing > 0.0 && shadow_settings.params.z != 0.0) {\n            shadow_visibility = cascaded_shadow_visibility(input, input.world_normal);\n        }",
        1,
    );

    // Sample before radius rejection and BRDF evaluation in every clustered
    // receiver path (legacy, PBR and ocean). Stock shaders keep point lighting.
    const CLUSTER_LIGHT: &str = "let light = dynamic_lights[cluster.indices[i]];";
    if source.matches(CLUSTER_LIGHT).count() < 2 {
        return Err("clustered emitter sampling anchors not found".to_string());
    }
    source = rt_sampled_light_loops(&source)?;
    source.push_str(include_str!("rt_resolution_read.wgsl"));

    // The enhanced ocean path has one outer guard that bypasses the common
    // visibility helper. Let the RT variant enter that same authoritative path.
    source = source.replace(
        "ENABLE_CASCADED_SHADOWS && shadow_settings.light_direction_enabled.w > 0.5",
        "(ENABLE_CASCADED_SHADOWS || ENABLE_RAY_TRACED_SUN) && shadow_settings.light_direction_enabled.w > 0.5",
    );
    Ok(source)
}

fn rt_alpha_storage_entry<T: Pod>(binding: u32) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility: wgpu::ShaderStages::FRAGMENT,
        ty: wgpu::BindingType::Buffer {
            ty: wgpu::BufferBindingType::Storage { read_only: true },
            has_dynamic_offset: false,
            // Validate table sizes at bind-group creation instead of first draw.
            min_binding_size: wgpu::BufferSize::new(std::mem::size_of::<T>() as u64),
        },
        count: None,
    }
}

fn rt_alpha_storage_entries() -> [wgpu::BindGroupLayoutEntry; 6] {
    [
        rt_alpha_storage_entry::<RtAlphaVertexGpu>(9),
        rt_alpha_storage_entry::<u32>(10),
        rt_alpha_storage_entry::<RtAlphaGeometryGpu>(11),
        rt_alpha_storage_entry::<RtAlphaMaterialGpu>(12),
        rt_alpha_storage_entry::<RtAlphaTextureGpu>(13),
        rt_alpha_storage_entry::<u32>(14),
    ]
}

fn create_ray_traced_shadow_receiver_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    let alpha_entries = rt_alpha_storage_entries();
    let cache_entries = rt_resolution::receiver_entries();
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("JKA hardware ray-traced sun/weather receiver layout"),
        entries: &[
            depth_array_texture_entry(0),
            comparison_sampler_entry(1),
            uniform_entry(2, wgpu::ShaderStages::FRAGMENT),
            uniform_entry(3, wgpu::ShaderStages::FRAGMENT),
            unfilterable_texture_entry_stages(
                4,
                wgpu::ShaderStages::FRAGMENT | wgpu::ShaderStages::COMPUTE,
            ),
            uniform_entry(
                5,
                wgpu::ShaderStages::FRAGMENT | wgpu::ShaderStages::COMPUTE,
            ),
            nonfiltering_sampler_entry(6, wgpu::ShaderStages::FRAGMENT),
            depth_array_texture_entry(7),
            wgpu::BindGroupLayoutEntry {
                binding: 8,
                visibility: wgpu::ShaderStages::FRAGMENT,
                ty: wgpu::BindingType::AccelerationStructure { vertex_return: false },
                count: None,
            },
            alpha_entries[0],
            alpha_entries[1],
            alpha_entries[2],
            alpha_entries[3],
            alpha_entries[4],
            alpha_entries[5],
            cache_entries[0],
            cache_entries[1],
        ],
    })
}

impl RayTracedShadowResources {
    fn scene(&self) -> RtReceiverScene<'_> {
        RtReceiverScene {
            tlas: &self._tlas,
            alpha_vertices: &self.alpha_vertex_buffer,
            alpha_indices: &self.alpha_index_buffer,
            alpha_geometries: &self.alpha_geometry_buffer,
            alpha_materials: &self.alpha_material_buffer,
            alpha_textures: &self.alpha_texture_buffer,
            alpha_texels: &self.alpha_texel_buffer,
        }
    }
}

/// The ray-query scene the receivers (and the sun compute pass) trace against.
struct RtReceiverScene<'a> {
    tlas: &'a wgpu::Tlas,
    alpha_vertices: &'a wgpu::Buffer,
    alpha_indices: &'a wgpu::Buffer,
    alpha_geometries: &'a wgpu::Buffer,
    alpha_materials: &'a wgpu::Buffer,
    alpha_textures: &'a wgpu::Buffer,
    alpha_texels: &'a wgpu::Buffer,
}

/// Group 3 of every ray-traced world/model pipeline: the ordinary sun-shadow
/// receiver resources plus the scene and the published sun-visibility cache.
/// One builder, because all three places that recreate it (initial build, alpha
/// table growth, receiver rebuild) must produce identical bindings.
fn create_rt_receiver_bind_group(
    device: &wgpu::Device,
    shadow: &ShadowResources,
    fog_control_buffer: &wgpu::Buffer,
    cascaded_shadow_mode: DynamicShadowsMode,
    layout: &wgpu::BindGroupLayout,
    scene: RtReceiverScene<'_>,
    sun_shadow_history: &rt_resolution::RtSunShadowHistory,
) -> wgpu::BindGroup {
    let shadow_sampler = if cascaded_shadow_mode == DynamicShadowsMode::CascadedShadowMaps {
        &shadow.bevy_sampler
    } else {
        &shadow.legacy_sampler
    };
    let shadow_array_view = &shadow._array_view;
    let sky_array_view = &shadow.sky_array_view;
    let receiver_buffer = &shadow.receiver_buffer;
    let weather_height_view = &shadow.weather_height_view;
    let weather_sampler = &shadow.weather_sampler;
    let weather_surface_buffer = &shadow.weather_surface_buffer;
    let RtReceiverScene {
        tlas,
        alpha_vertices: alpha_vertex_buffer,
        alpha_indices: alpha_index_buffer,
        alpha_geometries: alpha_geometry_buffer,
        alpha_materials: alpha_material_buffer,
        alpha_textures: alpha_texture_buffer,
        alpha_texels: alpha_texel_buffer,
    } = scene;
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("JKA hardware ray-traced sun/weather receiver bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(shadow_array_view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(shadow_sampler) },
            wgpu::BindGroupEntry { binding: 2, resource: receiver_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 3, resource: fog_control_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 4, resource: wgpu::BindingResource::TextureView(weather_height_view) },
            wgpu::BindGroupEntry { binding: 5, resource: weather_surface_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 6, resource: wgpu::BindingResource::Sampler(weather_sampler) },
            wgpu::BindGroupEntry { binding: 7, resource: wgpu::BindingResource::TextureView(sky_array_view) },
            wgpu::BindGroupEntry { binding: 8, resource: tlas.as_binding() },
            wgpu::BindGroupEntry { binding: 9, resource: alpha_vertex_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 10, resource: alpha_index_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 11, resource: alpha_geometry_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 12, resource: alpha_material_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 13, resource: alpha_texture_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 14, resource: alpha_texel_buffer.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 15, resource: sun_shadow_history.flags_uniform.as_entire_binding() },
            wgpu::BindGroupEntry { binding: 16, resource: wgpu::BindingResource::TextureView(&sun_shadow_history.published) },
        ],
    })
}

fn create_shadow_receiver_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    shadow_array_view: &wgpu::TextureView,
    shadow_sampler: &wgpu::Sampler,
    sky_array_view: &wgpu::TextureView,
    receiver_buffer: &wgpu::Buffer,
    fog_control_buffer: &wgpu::Buffer,
    weather_height_view: &wgpu::TextureView,
    weather_sampler: &wgpu::Sampler,
    weather_surface_buffer: &wgpu::Buffer,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("JKA cascaded sun/weather receiver bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: wgpu::BindingResource::TextureView(shadow_array_view),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: wgpu::BindingResource::Sampler(shadow_sampler),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: receiver_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: fog_control_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 4,
                resource: wgpu::BindingResource::TextureView(weather_height_view),
            },
            wgpu::BindGroupEntry {
                binding: 5,
                resource: weather_surface_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 6,
                resource: wgpu::BindingResource::Sampler(weather_sampler),
            },
            wgpu::BindGroupEntry {
                binding: 7,
                resource: wgpu::BindingResource::TextureView(sky_array_view),
            },
        ],
    })
}

fn create_shadow_resources(
    device: &wgpu::Device,
    receiver_layout: &wgpu::BindGroupLayout,
    caster_layout: &wgpu::BindGroupLayout,
    pipeline: wgpu::RenderPipeline,
    mask_pipeline: wgpu::RenderPipeline,
    bevy_pipeline: wgpu::RenderPipeline,
    bevy_mask_pipeline: wgpu::RenderPipeline,
    bevy_translucent_pipeline: wgpu::RenderPipeline,
    bevy_sky_pipeline: wgpu::RenderPipeline,
    fog_control_buffer: &wgpu::Buffer,
) -> ShadowResources {
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("JKA cascaded sun shadow array"),
        size: wgpu::Extent3d {
            width: SHADOW_MAP_SIZE,
            height: SHADOW_MAP_SIZE,
            depth_or_array_layers: SHADOW_CASCADES as u32,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: DEPTH_FORMAT,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::TEXTURE_BINDING,
        view_formats: &[],
    });
    let array_view = texture.create_view(&wgpu::TextureViewDescriptor {
        label: Some("JKA cascaded sun shadow array view"),
        format: Some(DEPTH_FORMAT),
        dimension: Some(wgpu::TextureViewDimension::D2Array),
        base_mip_level: 0,
        mip_level_count: Some(1),
        base_array_layer: 0,
        array_layer_count: Some(SHADOW_CASCADES as u32),
        aspect: wgpu::TextureAspect::DepthOnly,
        usage: Some(wgpu::TextureUsages::TEXTURE_BINDING),
    });
    let layer_views = (0..SHADOW_CASCADES)
        .map(|cascade| {
            texture.create_view(&wgpu::TextureViewDescriptor {
                label: Some("JKA cascaded sun shadow layer"),
                format: Some(DEPTH_FORMAT),
                dimension: Some(wgpu::TextureViewDimension::D2),
                base_mip_level: 0,
                mip_level_count: Some(1),
                base_array_layer: cascade as u32,
                array_layer_count: Some(1),
                aspect: wgpu::TextureAspect::DepthOnly,
                usage: Some(wgpu::TextureUsages::RENDER_ATTACHMENT),
            })
        })
        .collect::<Vec<_>>();
    let sky_texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("JKA cascaded shader-sun sky admission array"),
        size: wgpu::Extent3d {
            width: SHADOW_MAP_SIZE,
            height: SHADOW_MAP_SIZE,
            depth_or_array_layers: SHADOW_CASCADES as u32,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: DEPTH_FORMAT,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::TEXTURE_BINDING,
        view_formats: &[],
    });
    let sky_array_view = sky_texture.create_view(&wgpu::TextureViewDescriptor {
        label: Some("JKA cascaded shader-sun sky admission array view"),
        format: Some(DEPTH_FORMAT),
        dimension: Some(wgpu::TextureViewDimension::D2Array),
        base_mip_level: 0,
        mip_level_count: Some(1),
        base_array_layer: 0,
        array_layer_count: Some(SHADOW_CASCADES as u32),
        aspect: wgpu::TextureAspect::DepthOnly,
        usage: Some(wgpu::TextureUsages::TEXTURE_BINDING),
    });
    let sky_layer_views = (0..SHADOW_CASCADES)
        .map(|cascade| {
            sky_texture.create_view(&wgpu::TextureViewDescriptor {
                label: Some("JKA cascaded shader-sun sky admission layer"),
                format: Some(DEPTH_FORMAT),
                dimension: Some(wgpu::TextureViewDimension::D2),
                base_mip_level: 0,
                mip_level_count: Some(1),
                base_array_layer: cascade as u32,
                array_layer_count: Some(1),
                aspect: wgpu::TextureAspect::DepthOnly,
                usage: Some(wgpu::TextureUsages::RENDER_ATTACHMENT),
            })
        })
        .collect::<Vec<_>>();

    let legacy_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
        label: Some("JKA cascaded sun shadow legacy comparison sampler"),
        address_mode_u: wgpu::AddressMode::ClampToEdge,
        address_mode_v: wgpu::AddressMode::ClampToEdge,
        address_mode_w: wgpu::AddressMode::ClampToEdge,
        mag_filter: wgpu::FilterMode::Nearest,
        min_filter: wgpu::FilterMode::Nearest,
        compare: Some(wgpu::CompareFunction::LessEqual),
        ..Default::default()
    });
    let bevy_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
        label: Some("JKA Bevy CSM comparison sampler"),
        address_mode_u: wgpu::AddressMode::ClampToEdge,
        address_mode_v: wgpu::AddressMode::ClampToEdge,
        address_mode_w: wgpu::AddressMode::ClampToEdge,
        mag_filter: wgpu::FilterMode::Linear,
        min_filter: wgpu::FilterMode::Linear,
        mipmap_filter: wgpu::MipmapFilterMode::Nearest,
        compare: Some(wgpu::CompareFunction::GreaterEqual),
        ..Default::default()
    });
    let weather_fallback_texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("JKA weather-surface fallback heightfield"),
        size: wgpu::Extent3d {
            width: 1,
            height: 1,
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Rgba32Float,
        usage: wgpu::TextureUsages::TEXTURE_BINDING,
        view_formats: &[],
    });
    // Placeholder keeps the binding valid before the lazily built map field.
    // Once rain is first enabled this view is replaced by a second view of the
    // exact RGBA32F weather field used by GPU rain/materials (R=rain cover,
    // G=rendered topography height, B=physical upwardness, A=local basin score).
    let weather_height_view =
        weather_fallback_texture.create_view(&wgpu::TextureViewDescriptor::default());
    let weather_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
        label: Some("JKA weather-surface gather sampler"),
        address_mode_u: wgpu::AddressMode::ClampToEdge,
        address_mode_v: wgpu::AddressMode::ClampToEdge,
        address_mode_w: wgpu::AddressMode::ClampToEdge,
        mag_filter: wgpu::FilterMode::Nearest,
        min_filter: wgpu::FilterMode::Nearest,
        mipmap_filter: wgpu::MipmapFilterMode::Nearest,
        ..Default::default()
    });
    let receiver = ShadowReceiverUniform {
        view_proj: [Mat4::IDENTITY.to_cols_array_2d(); SHADOW_CASCADES],
        split_depths: bevy_cascade_bounds(),
        light_direction_enabled: [
            FALLBACK_SUN_DIRECTION[0],
            FALLBACK_SUN_DIRECTION[1],
            FALLBACK_SUN_DIRECTION[2],
            0.0,
        ],
        params: [SHADOW_MAP_SIZE as f32, 0.00035, 0.30, 0.0],
        camera_forward: [0.0, 0.0, -1.0, 0.0],
        cascade_texel_sizes: [0.0; 4],
        bevy_params: [BEVY_CSM_SHADOW_DEPTH_BIAS, BEVY_CSM_SHADOW_NORMAL_BIAS, BEVY_CSM_OVERLAP_PROPORTION, SHADOW_CASCADES as f32],
    };
    let receiver_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("JKA cascaded sun shadow receiver uniform"),
        contents: bytemuck::bytes_of(&receiver),
        usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
    });
    let weather_surface_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
        label: Some("JKA weather surface uniform"),
        contents: bytemuck::bytes_of(&WeatherSurfaceUniform {
            amount_distance: [0.0, weather::RAIN_WETNESS_FADE_START, weather::RAIN_WETNESS_FADE_END, 1.0],
            // The film fade is rewritten with the rest of the look on first use;
            // a non-zero range keeps the shader's smoothstep well defined until then.
            film_fade: [1.0, 2.0, 0.0, 0.0],
            ..bytemuck::Zeroable::zeroed()
        }),
        usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
    });
    let receiver_bind_group = create_shadow_receiver_bind_group(
        device,
        receiver_layout,
        &array_view,
        &legacy_sampler,
        &sky_array_view,
        &receiver_buffer,
        fog_control_buffer,
        &weather_height_view,
        &weather_sampler,
        &weather_surface_buffer,
    );
    /*let receiver_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("JKA cascaded sun shadow receiver bind group"),
        layout: receiver_layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: wgpu::BindingResource::TextureView(&array_view),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: wgpu::BindingResource::Sampler(&sampler),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: receiver_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: fog_control_buffer.as_entire_binding(),
            },
        ],
    });*/
    let mut caster_buffers = Vec::with_capacity(SHADOW_CASCADES);
    let mut caster_bind_groups = Vec::with_capacity(SHADOW_CASCADES);
    for _ in 0..SHADOW_CASCADES {
        let buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("JKA cascaded sun shadow caster uniform"),
            contents: bytemuck::bytes_of(&ShadowCasterUniform {
                view_proj: Mat4::IDENTITY.to_cols_array_2d(),
                camera_pos_time: [0.0; 4],
            }),
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("JKA cascaded sun shadow caster bind group"),
            layout: caster_layout,
            entries: &[wgpu::BindGroupEntry {
                binding: 0,
                resource: buffer.as_entire_binding(),
            }],
        });
        caster_buffers.push(buffer);
        caster_bind_groups.push(bind_group);
    }
    ShadowResources {
        _texture: texture,
        _array_view: array_view,
        layer_views,
        _sky_texture: sky_texture,
        sky_array_view,
        sky_layer_views,
        legacy_sampler,
        bevy_sampler,
        _weather_fallback_texture: weather_fallback_texture,
        weather_height_view,
        weather_sampler,
        receiver_buffer,
        weather_surface_buffer,
        receiver_bind_group,
        caster_buffers,
        caster_bind_groups,
        pipeline,
        mask_pipeline,
        bevy_pipeline,
        bevy_mask_pipeline,
        bevy_translucent_pipeline,
        bevy_sky_pipeline,
    }
}

fn bevy_cascade_bounds() -> [f32; SHADOW_CASCADES] {
    let base = (BEVY_CSM_MAXIMUM_DISTANCE / BEVY_CSM_FIRST_FAR_BOUND)
        .powf(1.0 / (SHADOW_CASCADES - 1) as f32);
    std::array::from_fn(|i| BEVY_CSM_FIRST_FAR_BOUND * base.powf(i as f32))
}

fn bevy_cascade_shadow_matrices(
    camera: &Camera,
    width: u32,
    height: u32,
    light_direction: Vec3,
) -> ([Mat4; SHADOW_CASCADES], [f32; SHADOW_CASCADES], [f32; SHADOW_CASCADES]) {
    // Faithful port of Bevy 0.19.1 bevy_light::cascade::{build_directional_light_cascades,
    // calculate_cascade}, with only the cascade distances scaled to JKA world units.
    let light_direction = light_direction.normalize_or_zero();
    let reference_up = if light_direction.dot(Vec3::Y).abs() > 0.95 { Vec3::Z } else { Vec3::Y };
    // Bevy builds cascades from the light transform's pure rotation. JKA stores
    // the sun's forward/travel direction directly, so construct the equivalent
    // zero-translation light view and transpose it to obtain world_from_light.
    let light_from_world = Mat4::look_to_rh(Vec3::ZERO, light_direction, reference_up);
    let world_from_light = light_from_world.transpose();
    let bounds = bevy_cascade_bounds();
    let overlap_factor = 1.0 - BEVY_CSM_OVERLAP_PROPORTION;
    let mut matrices = [Mat4::IDENTITY; SHADOW_CASCADES];
    let mut texel_sizes = [0.0; SHADOW_CASCADES];

    for cascade in 0..SHADOW_CASCADES {
        let near_bound = if cascade == 0 {
            BEVY_CSM_MINIMUM_DISTANCE
        } else {
            overlap_factor * bounds[cascade - 1]
        };
        let far_bound = bounds[cascade];
        let corners = camera.frustum_corners(width, height, near_bound, far_bound);

        let mut min = Vec3::splat(f32::MAX);
        let mut max = Vec3::splat(f32::MIN);
        for corner_world in corners {
            let corner_light_view = light_from_world.transform_point3(corner_world);
            min = min.min(corner_light_view);
            max = max.max(corner_light_view);
        }

        let body_diagonal = corners[0].distance_squared(corners[6]);
        let far_plane_diagonal = corners[4].distance_squared(corners[6]);
        let cascade_diameter = body_diagonal.max(far_plane_diagonal).sqrt().ceil();
        let cascade_texel_size = cascade_diameter / SHADOW_MAP_SIZE as f32;
        let near_plane_center = Vec3::new(
            (0.5 * (min.x + max.x) / cascade_texel_size).floor() * cascade_texel_size,
            (0.5 * (min.y + max.y) / cascade_texel_size).floor() * cascade_texel_size,
            max.z,
        );

        let world_from_light_transpose = world_from_light.transpose();
        let cascade_from_world = Mat4::from_cols(
            world_from_light_transpose.x_axis,
            world_from_light_transpose.y_axis,
            world_from_light_transpose.z_axis,
            (-near_plane_center).extend(1.0),
        );
        let r = (max.z - min.z).recip();
        let clip_from_cascade = Mat4::from_cols(
            Vec4::new(2.0 / cascade_diameter, 0.0, 0.0, 0.0),
            Vec4::new(0.0, 2.0 / cascade_diameter, 0.0, 0.0),
            Vec4::new(0.0, 0.0, r, 0.0),
            Vec4::new(0.0, 0.0, 1.0, 1.0),
        );
        matrices[cascade] = clip_from_cascade * cascade_from_world;
        texel_sizes[cascade] = cascade_texel_size;
    }

    (matrices, bounds, texel_sizes)
}

#[allow(clippy::too_many_arguments)]
fn create_world_froxel_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    uniform_buffer: &wgpu::Buffer,
    fog_buffer: &wgpu::Buffer,
    sun_shadow_array: &wgpu::TextureView,
    sky_admission_array: &wgpu::TextureView,
    light_buffer: &wgpu::Buffer,
    cluster_buffer: &wgpu::Buffer,
    lighting_settings_buffer: &wgpu::Buffer,
    local_shadow_cube: &wgpu::TextureView,
    local_shadow_sampler: &wgpu::Sampler,
    rain_occlusion_height: &wgpu::TextureView,
    wind_noise: &wgpu::TextureView,
    wind_noise_sampler: &wgpu::Sampler,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("JKA world froxel volumetric fog bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry {
                binding: 0,
                resource: uniform_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 1,
                resource: fog_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 2,
                resource: wgpu::BindingResource::TextureView(sun_shadow_array),
            },
            wgpu::BindGroupEntry {
                binding: 3,
                resource: light_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 4,
                resource: cluster_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 5,
                resource: lighting_settings_buffer.as_entire_binding(),
            },
            wgpu::BindGroupEntry {
                binding: 6,
                resource: wgpu::BindingResource::TextureView(local_shadow_cube),
            },
            wgpu::BindGroupEntry {
                binding: 7,
                resource: wgpu::BindingResource::Sampler(local_shadow_sampler),
            },
            wgpu::BindGroupEntry {
                binding: 8,
                resource: wgpu::BindingResource::TextureView(rain_occlusion_height),
            },
            wgpu::BindGroupEntry {
                binding: 9,
                resource: wgpu::BindingResource::TextureView(wind_noise),
            },
            wgpu::BindGroupEntry {
                binding: 10,
                resource: wgpu::BindingResource::Sampler(wind_noise_sampler),
            },
            wgpu::BindGroupEntry {
                binding: 11,
                resource: wgpu::BindingResource::TextureView(sky_admission_array),
            },
        ],
    })
}

fn create_ssao_temporal_bind_groups(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    linear_depth_view: &wgpu::TextureView,
    history: Option<&TemporalSsaoHistory>,
    sampler: &wgpu::Sampler,
    buffer: &wgpu::Buffer,
) -> Option<[wgpu::BindGroup; 2]> {
    let history = history?;
    Some(std::array::from_fn(|history_index| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("JKA temporal SSAO bind group"),
            layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: wgpu::BindingResource::TextureView(linear_depth_view),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::TextureView(&history.views[history_index]),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: wgpu::BindingResource::Sampler(sampler),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: buffer.as_entire_binding(),
                },
            ],
        })
    }))
}

fn create_ssr_temporal_bind_groups(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    scene_view: &wgpu::TextureView,
    linear_depth_view: &wgpu::TextureView,
    history: Option<&TemporalSsrHistory>,
    sampler: &wgpu::Sampler,
    buffer: &wgpu::Buffer,
    weather_height_view: &wgpu::TextureView,
    weather_sampler: &wgpu::Sampler,
    weather_surface_buffer: &wgpu::Buffer,
    reflection_mask_view: &wgpu::TextureView,
    ssr_visibility_view: Option<&wgpu::TextureView>,
) -> Option<[wgpu::BindGroup; 2]> {
    let history = history?;
    let ssr_visibility_view = ssr_visibility_view?;
    Some(std::array::from_fn(|history_index| {
        device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("JKA temporal SSR bind group"),
            layout,
            entries: &[
                wgpu::BindGroupEntry {
                    binding: 0,
                    resource: wgpu::BindingResource::TextureView(scene_view),
                },
                wgpu::BindGroupEntry {
                    binding: 1,
                    resource: wgpu::BindingResource::Sampler(sampler),
                },
                wgpu::BindGroupEntry {
                    binding: 2,
                    resource: wgpu::BindingResource::TextureView(linear_depth_view),
                },
                wgpu::BindGroupEntry {
                    binding: 3,
                    resource: wgpu::BindingResource::TextureView(
                        &history.radiance_views[history_index],
                    ),
                },
                wgpu::BindGroupEntry {
                    binding: 4,
                    resource: wgpu::BindingResource::TextureView(
                        &history.depth_views[history_index],
                    ),
                },
                wgpu::BindGroupEntry {
                    binding: 5,
                    resource: buffer.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 6,
                    resource: wgpu::BindingResource::TextureView(weather_height_view),
                },
                wgpu::BindGroupEntry {
                    binding: 7,
                    resource: wgpu::BindingResource::Sampler(weather_sampler),
                },
                wgpu::BindGroupEntry {
                    binding: 8,
                    resource: weather_surface_buffer.as_entire_binding(),
                },
                wgpu::BindGroupEntry {
                    binding: 9,
                    resource: wgpu::BindingResource::TextureView(reflection_mask_view),
                },
                wgpu::BindGroupEntry {
                    binding: 10,
                    resource: wgpu::BindingResource::TextureView(ssr_visibility_view),
                },
            ],
        })
    }))
}

